import{_ as t,c as s,o as l,j as e,a as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"四庫全書提要","description":"子夏易傳 - 四庫全書提要","frontmatter":{"title":"四庫全書提要","description":"子夏易傳 - 四庫全書提要"},"headers":[],"relativePath":"classics/zixia/002.md","filePath":"classics/zixia/002.md"}'),n={name:"classics/zixia/002.md"};function r(c,a,o,p,d,u){return l(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"四庫全書提要",tabindex:"-1"},[i("四庫全書提要 "),e("a",{class:"header-anchor",href:"#四庫全書提要","aria-label":"Permalink to “四庫全書提要”"},"​")],-1),e("p",null,"《子夏易傳》·十一卷（內府藏本）",-1),e("p",null,"舊本題“卜子夏撰”。案說《易》之家，最古者莫若是書。其偽中生偽，至一至再而未已者，亦莫若是書。《唐會要》載開元七年詔：“子夏《易傳》，近無習者，令儒官詳定。”劉知幾議曰：“《漢志》《易》有十三家而無子夏作傳者，至梁阮氏《七錄》，始有《子夏易》六卷，或雲韓嬰作，或雲丁寬作。然據《漢書》，《韓易》十二篇，《丁易》八篇，求其符合，事殊隳刺，必欲行用，深以為疑。”",-1),e("p",null,"司馬貞議亦曰“案劉向《七略》有《子夏易傳》，但此書不行已久，今所存多失真本。荀勖《中經簿》雲：《子夏傳》四卷，或雲丁寬。是先達疑非子夏矣。又《隋書·經籍志》雲：《子夏傳》殘闕，梁六卷，今二卷。知其書錯繆多矣。又王儉《七志》引劉向《七略》雲：《易傳》子夏，韓氏嬰也。今題不稱韓氏而載薛虞記，其質粗略，旨趣非遠，無益後學”云云。是唐以前所謂《子夏傳》，已為偽本。",-1),e("p",null,"晁說之《傳易堂記》又稱：“今號為《子夏傳》者，乃唐張弧之《易》”（案弧唐末為大理寺評事，有《素履子》，別著錄），是唐時又一偽本並行。故宋《國史志》以《假託子夏易傳》與《真子夏易傳》兩列其目，而《崇文總目》亦稱此書篇第，略依王氏，決非卜子夏之文也。",-1),e("p",null,"朱彝尊《經義考》，證以陸德明《經典釋文》、李鼎祚《周易集解》、王應麟《困學紀聞》所引，皆今本所無。德明、鼎祚猶曰在張弧以前，應麟乃南宋末人，何以當日所見與今本又異？然則今本又出偽託，不但非子夏書，亦並非張弧書矣。流傳既久，姑存以備一家云爾。（謹案：唐徐堅《初學記》以太宗御製升列歷代之前，蓋臣子尊君之大義。焦竑《國史經籍志》、朱彝尊《經義考》並踵前規。臣等編摩《四庫》，初亦恭錄御定《易經通注》、御纂《周易折中》、御纂《周易述義》弁冕諸經。仰蒙指示，命移冠國朝著述之首，俾尊卑有序而時代不淆。聖度謙沖，酌中立憲，實為千古之大公。",-1),e("p",null,"謹恪遵彝訓，仍託始於《子夏易傳》，併發凡於此，著《四庫》之通例焉。又案：託名之書有知其贗作之人者，有不知其贗作之人者，不能一一歸其時代，故《漢書·藝文志》仍從其所託之時代為次。今亦悉從其例。）",-1)])])}const f=t(n,[["render",r]]);export{_ as __pageData,f as default};
